 "content": "def transform(grid):
    """Project rays from 3/2 marker centers across parallel 2-bars."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The long 2-lines are the structural bars; their orientation determines
    # the perpendicular ray direction. Require a substantial run of 2s.
    horizontal = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= max(4, w // 3)]
    vertical = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= max(4, h // 3)]
    if len(vertical) >= len(horizontal):
        orientation = "vertical"
        bars = vertical
    else:
        orientation = "horizontal"
        bars = horizontal

    # Find each 3x3 ring of 3s with a central 2.
    markers = []
    for r in range(h - 2):
        for c in range(w - 2):
            if grid[r + 1][c + 1] != 2:
                continue
            if all(grid[r + dr][c + dc] == 3
                   for dr, dc in ((0, 0), (0, 1), (0, 2), (1, 0),
                                  (1, 2), (2, 0), (2, 1), (2, 2))):
                markers.append((r + 1, c + 1))

    crossings = set()
    for mr, mc in markers:
        if orientation == "vertical":
            # A marker on a vertical 2-bar sends a horizontal ray.
            for c in range(w):
                if grid[mr][c] == 0:
                    out[mr][c] = 1
            crossings.update((mr, bc) for bc in bars if bc != mc)
        else:
            # A marker on a horizontal 2-bar sends a vertical ray.
            for r in range(h):
                if grid[r][mc] == 0:
                    out[r][mc] = 1
            crossings.update((br, mc) for br in bars if br != mr)

    # Each ray meeting another parallel 2-bar produces a 3x3 1-frame,
    # retaining the 2 at the intersection center.
    for cr, cc in crossings:
        for r in range(max(0, cr - 1), min(h, cr + 2)):
            for c in range(max(0, cc - 1), min(w, cc + 2)):
                if (r, c) != (cr, cc):
                    out[r][c] = 1

    return out
"
